    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
        ref_future = pool.submit(_run_worker, REF_VENV, ref_trace, ref_log)
        cand_future = pool.submit(_run_worker, candidate, cand_trace, cand_log)
