class Mock:
    def __init__(self) -> None:
        self.captured: list[dict] = []
110→        self.queue: list[dict] = []
        self.lock = threading.Lock()

    def begin(self) -> int:
        with self.lock:
            self.queue.clear()
            return len(self.captured)

    def push(self, *responses: dict) -> None:
        with self.lock:
120→            self.queue.extend(responses)

    def pop(self) -> dict:
        with self.lock:
            if self.queue:
                return self.queue.pop(0)
            return _ok(XML_DONE, reasoning="fallback")

    def record(self, path: str, body: dict) -> None:
        with self.lock:
130→            self.captured.append({"path": path.split("?", 1)[0], "body": body})

    def since(self, mark: int) -> list[dict]:
        with self.lock:
            return list(self.captured[mark:])


